--
-- Table structure for table `chatmessage`
--

DROP TABLE IF EXISTS `chatmessage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chatmessage` (
  `is_bot` tinyint(1) NOT NULL,
  `source` int DEFAULT NULL,
  `mark_status` int DEFAULT NULL,
  `mark_user` int DEFAULT NULL,
  `mark_user_name` varchar(255) DEFAULT NULL,
  `message` text,
  `extra` varchar(4096) DEFAULT NULL,
  `type` varchar(255) NOT NULL,
  `category` varchar(32) NOT NULL,
  `flow_id` char(32) NOT NULL,
  `chat_id` varchar(255) DEFAULT NULL,
  `user_id` varchar(255) DEFAULT NULL,
  `liked` int DEFAULT NULL,
  `solved` int DEFAULT NULL,
  `copied` int DEFAULT NULL,
  `sender` varchar(255) DEFAULT NULL,
  `intermediate_steps` text,
  `files` varchar(4096) DEFAULT NULL,
  `remark` varchar(4096) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `id` int NOT NULL AUTO_INCREMENT,
  `receiver` json DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_chatmessage_chat_id` (`chat_id`),
  KEY `ix_chatmessage_flow_id` (`flow_id`),
  KEY `ix_chatmessage_user_id` (`user_id`),
