INSERT INTO `config` VALUES ('initdb_config','knowledges: # 知识库相关配置\n  unstructured_api_url: \"\"  # 非必填，若要开启溯源能力则必填。使用毕昇官网提供的测试服务，可以填入地址：https://bisheng.dataelem.com/api/v1/etl4llm/predict，如果在私有环境部署了bisheng-unstructured服务，可以填入地址：http://ip:port/v1/etl4llm/predict。注意：添加地址后，需要手动刷新页面后在知识库中上传文档。\n\nllm_request:\n  # 控制技能 LLM 组件模型访问的超时配置, 以下是默认值\n  request_timeout: 600\n  max_retries: 1\n\ndefault_operator:\n  # 使用免登录链接的方式需要配置，因为免登录链接相当于不知道用户信息，我们系统会自动把这些行为记录到某个用户头上，这里用来配置该用户的id\n  user: 1\n  enable_guest_access: true # 免登录链接是否可访问\n\n# 密码安全相关配置\npassword_conf:\n  # 密码超过X天必须进行修改, 登录提示重新修改密码。大于0策略才生效\n  password_valid_period: 200\n  # 登录错误时间窗口,单位分钟。在错误时间窗口内超过最大错误次数会封禁用户，password_valid_period和login_error_time_window都大于0才生效\n  login_error_time_window: 5\n  # 最大错误次数，超过后会封禁用户，大于0时生效\n  max_error_times: 0\n\nsystem_login_method:\n  # 是否允许多点登录\n  allow_multi_login: true\n  # sso系统登录配置（毕昇商业扩展套件功能，开源版无需配置）\n  gateway_login: false # 是否开启sso登录\n  admin_username: admin # 从 SSO/LDAP 注册的管理员用户名\n\n# 登陆页面是否需要输入验证码，可设置为True或False\nuse_captcha: False\n\n# 会话窗口底部提示文案\ndialog_tips:\n  \"内容由AI生成，仅供参考！\"\n\nenv:\n  # 聊天窗口快捷搜索功能使用的搜索引擎，默认为百度，可以配置为内部文档搜索\n  # dialog_quick_search: http://www.baidu.com/s?wd=\n  # 当用户的环境前面的网关，不能在同一个端口上既有http又有socket时，需要这个配置，将两个请求区分开，默认可以不用\n  # websocket_url: 192.168.106.120:3003\n  office_url: http://IP:8701 # onlyoffice 组件地址，需要浏览器能直接访问\n  # 是否展示前端界面上的github和帮助链接\n  show_github_and_help: true\n  # 是否开启注册\n  enable_registration: true\n\nworkflow:\n  # 节点运行最大步数\n  max_steps: 50\n  # 等待用户输入的超时时间，单位分钟\n  timeout: 720\n',NULL,'2025-01-12 12:46:51','2025-02-18 11:58:38',1),('knowledge_llm','{\"embedding_model_id\": 4, \"source_model_id\": 6, \"extract_title_model_id\": 6, \"qa_similar_model_id\": 6}',NULL,'2025-01-12 12:54:15','2025-01-23 10:11:08',2),('evaluation_llm','{\"model_id\": 6}',NULL,'2025-01-12 12:54:15','2025-01-23 10:11:23',3),('assistant_llm','{\"llm_list\": [{\"model_id\": 6, \"agent_executor_type\": \"ReAct\", \"knowledge_max_content\": 15000, \"knowledge_sort_index\": true, \"streaming\": true, \"default\": true}], \"auto_llm\": {\"model_id\": 6, \"agent_executor_type\": \"ReAct\", \"knowledge_max_content\": 15000, \"knowledge_sort_index\": false, \"streaming\": true, \"default\": false}}',NULL,'2025-01-12 12:54:15','2025-01-23 10:11:17',4),('workflow_llm','{\"model_id\": 6}',NULL,'2025-01-12 12:55:34','2025-01-23 10:11:00',5);
/*!40000 ALTER TABLE `config` ENABLE KEYS */;
UNLOCK TABLES;

