INSERT INTO `t_gpts_tools` VALUES ('时间',NULL,'返回当前时间，如果未指定时区，将使用 UTC+8 时间','get_current_time',1,1,0,'[]',NULL,'2024-03-29 14:36:00','2025-01-12 12:46:51','{}',1),('计算器',NULL,'使用 Python 内置工具进行数学表达式计算','calculator',2,1,0,'[]',NULL,'2024-03-29 14:37:11','2025-01-12 12:46:51','{}',2),('论文获取',NULL,'从 Arxiv 网站检索论文的工具，输入为检索关键词。','arxiv',3,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"search query to look up\"}]',NULL,'2024-03-29 14:39:37','2025-01-12 12:46:51','{}',3),('Dalle3绘画',NULL,'根据提示词生成图像。','dalle_image_generator',4,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"Description about image.\"}]',NULL,'2024-03-29 14:40:32','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.dalle_image_generator\"}',4),('Bing web搜索',NULL,'使用 query 进行 Bing 搜索并返回返回结果。','bing_search',5,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"query to look up in Bing search\"}]',NULL,'2024-03-29 14:41:16','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.bing_search\"}',5),('代码执行器',NULL,'可以执行 Python  和 shell 代码，并在 600 秒内返回结果，适合处理数学、编程、图片和文件等问题场景。','bisheng_code_interpreter',6,1,0,'[{\"in\": \"query\", \"name\": \"python_code\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"The pure python script to be evaluated. \\nThe contents will be in main.py. \\nIt should not be in markdown format.\"}]',NULL,'2024-03-29 14:42:17','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.bisheng_code_interpreter\"}',6),('人员所有公司',NULL,'可以通过公司名称或ID和人名获取企业人员的所有相关公司，包括其担任法人、股东、董监高的公司信息','tianyancha_all_companys_by_company',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"human who you want to search\"}, {\"in\": \"query\", \"name\": \"name\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"company name which human worked\"}]',NULL,'2024-03-29 14:44:34','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',7),('搜索企业',NULL,'可以通过关键词获取企业列表，企业列表包括公司名称或ID、类型、成立日期、经营状态、统一社会信用代码等字段的详细信息','tianyancha_search_company',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:50:07','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',9),('企业基本信息',NULL,'可以通过公司名称或ID获取企业基本信息，企业基本信息包括公司名称或ID、类型、成立日期、经营状态、注册资本、法人、工商注册号、统一社会信用代码、组织机构代码、纳税人识别号等字段信息','tianyancha_get_company_baseinfo',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:51:06','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',10),('企业知识产权信息',NULL,'可以通过公司名称或ID获取包含商标、专利、作品著作权、软件著作权、网站备案等维度的相关信息','tianyancha_ip_rights',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:51:33','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',11),('企业司法风险',NULL,'可以通过公司名称或ID获取包含法律诉讼、法院公告、开庭公告、失信人、被执行人、立案信息、送达公告等维度的相关信息','tianyancha_judicial_risk',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:52:13','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',12),('企业法律诉讼',NULL,'可以通过公司名称或ID获取企业法律诉讼信息，法律诉讼包括案件名称、案由、案件身份、案号等字段的详细信息','tianyancha_law_suit_case',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:52:36','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',13),('企业工商信息',NULL,'可以通过公司名称或ID获取包含企业基本信息、主要人员、股东信息、对外投资、分支机构等维度的相关信息','tianyancha_ic_info',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:53:06','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',14),('企业工商信息变更记录',NULL,'可以通过公司名称或ID获取企业变更记录，变更记录包括工商变更事项、变更前后信息等字段的详细信息','tianyancha_company_change_info',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:54:02','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',15),('企业股东',NULL,'可以通过公司名称或ID获取企业股东信息，股东信息包括股东名、出资比例、出资金额、股东总数等字段的详细信息','tianyancha_company_holders',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:54:28','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',16),('企业天眼风险',NULL,'可以通过关键字（公司名称、公司id、注册号或社会统一信用代码）获取企业相关天眼风险列表，包括企业自身/周边/预警风险信息。','tianyancha_riskinfo',7,1,0,'[{\"in\": \"query\", \"name\": \"query\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"搜索关键字（公司名称、公司id、注册号或社会统一信用代码）\"}]',NULL,'2024-03-29 14:54:57','2025-01-12 12:46:51','{\"&initdb_conf_key\": \"gpts.tools.tianyancha\"}',17),('股票实时行情',NULL,'查询中国A股（沪深北交易所）股票或指数的实时行情数据，返回：现价、涨跌额、涨跌幅、成交量、成交额。','sina_realtime_info',8,1,0,'[{\"in\": \"query\", \"name\": \"prefix\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"前缀。如果是\\\"stock_symbol\\\"传入的为股票代码，则需要传入s_;\\n如果\\\"stock_symbol\\\"传入的为指数代码，则为空。\"}, {\"in\": \"query\", \"name\": \"stock_exchange\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"交易所简写。股票上市的交易所，或者发布行情指数的交易所。可选项有\\\"sh\\\"(上海证券交易所)、\\\" sz\\\"( 深圳证券交易所)、\\\"bj\\\"( 北京证券交易所)\"}, {\"in\": \"query\", \"name\": \"stock_symbol\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"6位数字的股票或者指数代码。\\n参考信息：\\n- 如果问题中未给出，可能需要上网查询。\\n- 上交所股票通常以 6 开头，深交所股票通常以 0、3 开头，北交所股票通常以 8 开头。\\n- 上交所行情指数通常以 000 开头，深交所指数通常以 399 开头。同一个指数可能会同时在两个交易所发布，例如沪深 300 有\\\"sh000300\\\"和\\\"sz399300\\\"两个代码。\"}]',NULL,'2024-03-29 14:56:15','2025-01-12 12:46:51',NULL,18),('股票历史行情',NULL,'查询中国A股（沪深北交易所）股票或指数的的历史行情数据，返回：时间、开盘价、最高价、最低价、收盘价、成交量（股）。','sina_history_KLine',8,1,0,'[{\"in\": \"query\", \"name\": \"date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"需要查询的时间，按照”2024-03-26“格式，传入日期\"}, {\"in\": \"query\", \"name\": \"stock_exchange\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"交易所简写。股票上市的交易所，或者发布行情指数的交易所。可选项有\\\"sh\\\"(上海证券交易所)、\\\" sz\\\"( 深圳证券交易所)、\\\"bj\\\"( 北京证券交易所)\"}, {\"in\": \"query\", \"name\": \"stock_symbol\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"6位数字的股票或者指数代码。\\n参考信息：\\n- 如果问题中未给出，可能需要上网查询。\\n- 上交所股票通常以 6 开头，深交所股票通常以 0、3 开头，北交所股票通常以 8 开头。\\n- 上交所行情指数通常以 000 开头，深交所指数通常以 399 开头。同一个指数可能会同时在两个交易所发布，例如沪深 300 有\\\"sh000300\\\"和\\\"sz399300\\\"两个代码。\"}]',NULL,'2024-03-29 14:56:38','2025-01-12 12:46:51',NULL,19),('社会融资规模增量',NULL,'中国社会融资规模增量月度统计数据。返回数据包括：月份，社会融资规模增量(单位：亿元)，社融增量分项数据。分项数据具体包括：人民币贷款，外币贷款，委托贷款，信托贷款，未贴现银行承兑汇票，企业债券，非金融企业境内股票融资。','macro_china_shrzgm',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 14:59:06','2025-01-12 12:46:51',NULL,20),('GDP',NULL,' 中国国内生产总值（GDP）季度统计数据。返回数据包括：季度，当年累计GDP 绝对值及同比增长情况，第一、二、三产业 GDP 绝对值以及同比增长情况。','macro_china_gdp_yearly',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 14:59:38','2025-01-12 12:46:51',NULL,21),('CPI',NULL,'中国居民消费价格指数(CPI，上年同月=100)月度统计数据。返回数据包括：月份，全国当月 CPI，全国当月同比增长，全国当月环比增长，全国当年 CPI 累计值；城市当月 CPI，城市当月同比增长，城市当月环比增长，城市当年 CPI 累计值；农村当月 CPI，农村当月同比增长，农村当月环比增长，农村当年 CPI 累计值。','macro_china_cpi',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 15:00:00','2025-01-12 12:46:51',NULL,22),('PPI',NULL,'中国工业品出厂价格指数（PPI）月度统计数据。返回数据包括：月份，当月 PPI，当月同比增长，当年 PPI 累计值。','macro_china_ppi',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 15:00:24','2025-01-12 12:46:51',NULL,23),('货币供应量',NULL,'中国货币供应量月度统计数据。返回数据包括：月份，当月 M0、M1、M2数量以及同、环比情况。','macro_china_money_supply',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 15:00:54','2025-01-12 12:46:51',NULL,24),('社会消费品零售总额',NULL,'中国社会消费品零售总额月度统计数据。返回数据包括：月份，当月总额以及同、环比，当年累计总额以及同比情况。','macro_china_consumer_goods_retail',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-03-29 15:01:47','2025-01-12 12:46:51',NULL,25),('PMI',NULL,'中国 PMI （采购经理人指数）月度统计数据。返回数据包括：月份制造业 PMI，制造业 PMI 同比增长，非制造业 PMI，非制造业 PMI 同比增长。','macro_china_pmi',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-04-15 12:01:11','2025-01-12 12:46:51',NULL,26),('中美国债收益率',NULL,'本接口返回指定时间段[start_date,end_date]内交易日的中美两国的 2 年、5 年、10 年、30 年、10 年-2 年收益率数据。start_date表示起始日期，end_date表示结束日期，日期格式例如 2024-04-07','macro_bond_zh_us_rate',8,1,0,'[{\"in\": \"query\", \"name\": \"start_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"开始月份, 使用YYYY-MM-DD 方式表示\"}, {\"in\": \"query\", \"name\": \"end_date\", \"schema\": {\"type\": \"string\"}, \"required\": true, \"description\": \"结束月份, 使用YYYY-MM-DD 方式表示\"}]',NULL,'2024-04-15 12:03:27','2025-01-12 12:46:51',NULL,27);
